                if(Build.VERSION.SDK_INT>=28)bitmap=ImageDecoder.decodeBitmap(ImageDecoder.createSource(getContentResolver(),source),(decoder,info,s)->{originalW=info.getSize().getWidth();originalH=info.getSize().getHeight();float f=Math.min(1,1600f/Math.max(originalW,originalH));decoder.setTargetSize(Math.max(1,Math.round(originalW*f)),Math.max(1,Math.round(originalH*f)));decoder.setAllocator(ImageDecoder.ALLOCATOR_SOFTWARE);});
