    @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==451&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)save();}
    @Override public void onBackPressed(){if(exporting){new AlertDialog.Builder(this).setTitle("Cancelar exportação?").setMessage("A cópia incompleta será removida.").setPositiveButton("Cancelar exportação",(d,w)->cancellation.cancelled.set(true)).setNegativeButton("Continuar",null).show();return;}if(canvas!=null&&canvas.dirty()){new AlertDialog.Builder(this).setTitle("Descartar edição?").setPositiveButton("Descartar",(d,w)->finish()).setNegativeButton("Continuar editando",null).show();return;}super.onBackPressed();}
